import{_ as l,a0 as a,w as i,s as d,I as r,x as s,a1 as p,A as n,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"開源軟件安全嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"開源軟件安全嗎？ | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開源軟件安全嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開源軟件安全嗎？ | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20210718 Is Open-Source Software Secure","title":"開源軟件安全嗎？","tag":"202301","desc":""},"relativePath":"202301/20210718 Is Open-Source Software Secure.md","filePath":"[post].md"}'),u={name:"202301/20210718 Is Open-Source Software Secure.md"};function f(m,t,g,T,b,x){const e=a("Link");return i(),d("div",null,[t[30]||(t[30]=r("h1",{id:"開源軟件安全嗎",tabindex:"-1"},[s("開源軟件安全嗎？ "),r("a",{class:"header-anchor",href:"#開源軟件安全嗎","aria-label":"Permalink to “開源軟件安全嗎？”"},"​")],-1)),t[31]||(t[31]=r("p",null,[r("img",{src:"https://news.itsfoss.com/content/images/size/w2000/wordpress/2021/07/open-source-security.jpg",alt:""})],-1)),r("p",null,[t[1]||(t[1]=s("作為一個偏愛 ",-1)),p(e,{href:"https://news.itsfoss.com/linux-foundation-linux-desktop/"},{default:n(()=>[...t[0]||(t[0]=[s("在桌面電腦上使用 Linux",-1)])]),_:1}),t[2]||(t[2]=s("，並鼓勵使用開源軟件的人，你可能期待就標題中提出的問題得到一個響亮的",-1)),t[3]||(t[3]=r("strong",null,"肯定",-1)),t[4]||(t[4]=s("回答。",-1))]),t[32]||(t[32]=r("p",null,"然而，我並不打算僅限於討論開源軟件的優點。讓我們一起探索更多觀點！",-1)),t[33]||(t[33]=r("p",null,"在本文，我計劃分享我關於開源軟件是否安全的思考，以及哪些事情與開源軟件的安全性相關。",-1)),t[34]||(t[34]=r("h3",{id:"為什麼你需要關注開源軟件是否安全",tabindex:"-1"},[s("為什麼你需要關注開源軟件是否安全？ "),r("a",{class:"header-anchor",href:"#為什麼你需要關注開源軟件是否安全","aria-label":"Permalink to “為什麼你需要關注開源軟件是否安全？”"},"​")],-1)),r("p",null,[t[6]||(t[6]=s("不論你是使用 ",-1)),p(e,{href:"https://itsfoss.com/what-is-linux-distribution/"},{default:n(()=>[...t[5]||(t[5]=[s("Linux",-1)])]),_:1}),t[7]||(t[7]=s(" 系統還是使用其他類型的操作系統，你都會在某種程度上（直接地/間接地）被開源軟件所包圍。",-1))]),t[35]||(t[35]=o('<p>舉個例子，大多數專有軟件工具依賴於某種形式的開源庫來保證其正常工作。</p><p>此外，各種規模的公司（包括谷歌、微軟和 Facebook）依賴開源軟件或者以某種途徑向開源社區貢獻資源是有原因的。</p><p>因此，開源軟件的安全性是有必要了解的。</p><h3 id="有關開源軟件安全性的迷思" tabindex="-1">有關開源軟件安全性的迷思 <a class="header-anchor" href="#有關開源軟件安全性的迷思" aria-label="Permalink to “有關開源軟件安全性的迷思”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/wordpress/2021/07/hacker-exploit-illustration.png" alt=""></p><p>雖然有多種理由證明開源軟件在安全性方面的缺陷，然而其中一些實際毫無意義。</p><h4 id="任何人都可以查看並惡意利用開源軟件代碼" tabindex="-1">任何人都可以查看並惡意利用開源軟件代碼 <a class="header-anchor" href="#任何人都可以查看並惡意利用開源軟件代碼" aria-label="Permalink to “任何人都可以查看並惡意利用開源軟件代碼”">​</a></h4><p>是的，開源軟件代碼對於任何人都是可訪問的。但是你可以查看代碼並不意味着你可以利用它。</p><p><strong>不現實。</strong></p><p>即使任何人都可以復刻（或者拷貝）該軟件，原始軟件也不能輕易地被修改使用。</p><p>通常，項目維護人員（或者維護團隊）管理代碼倉庫，並且接受來自貢獻者的提交。開源軟件代碼在接受之前會被審查。沒有人可以就這樣劫持代碼。</p><p><strong>不論是開源軟件還是閉源軟件，攻擊者都需要付出努力來利用軟件中的代碼漏洞或者添加惡意代碼。</strong></p><h4 id="沒有專職團隊-安全性無從談起" tabindex="-1">沒有專職團隊，安全性無從談起 <a class="header-anchor" href="#沒有專職團隊-安全性無從談起" aria-label="Permalink to “沒有專職團隊，安全性無從談起”">​</a></h4><p>很多人相信如果開源軟件沒有專職人員或者專職團隊，維護軟件安全性是困難的。</p><p>恰恰相反，由於各種各樣類型的貢獻者的加入與離開，開源軟件獲得了來自更大範圍的開發者的更多關注。</p><p>他們可能比由專有軟件所聘用的少數開發者更能夠發現安全問題。</p><p>一些來自 Mozilla 等同類公司的項目擁有自己的專職團隊來高效處理安全問題。同樣的，大部分成功的開源項目擁有大量的資源用於保障安全性。</p><p>因此，開源軟件的生態系統是安全性的組合包。即使沒有專職團隊，開源項目也可以得到來自各類貢獻者的幫助，他們中的一些很大程度上是有利可圖的，這有助於他們投入更多的精力。</p><h3 id="開源軟件是安全的-以下是原因" tabindex="-1">開源軟件是安全的，以下是原因 <a class="header-anchor" href="#開源軟件是安全的-以下是原因" aria-label="Permalink to “開源軟件是安全的，以下是原因”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/wordpress/2021/07/open-source-security-illustration.png" alt=""></p><p>既然我們已經澄清了這些有關開源軟件安全性的迷思，讓我重點展示一下開源軟件是如何處理安全問題的。</p><p>換句話説，開源軟件在安全性上的優勢。</p>',22)),r("p",null,[t[9]||(t[9]=s("請不要忘記，開源軟件的優勢也是 ",-1)),p(e,{href:"https://itsfoss.com/linux-better-than-windows/"},{default:n(()=>[...t[8]||(t[8]=[s("Linux 比 Windows 更好",-1)])]),_:1}),t[10]||(t[10]=s(" 的一些原因。",-1))]),t[36]||(t[36]=o('<h4 id="更多的眼晴關注開源軟件代碼" tabindex="-1">更多的眼晴關注開源軟件代碼 <a class="header-anchor" href="#更多的眼晴關注開源軟件代碼" aria-label="Permalink to “更多的眼晴關注開源軟件代碼”">​</a></h4><p>不像專有軟件，（對開源軟件的）代碼訪問並不侷限於少數幾個開發者。</p><p>一些開源項目甚至可能擁有數以萬記的開發者可以查看代碼、審查它們並標記和修復其中的安全性問題。</p><p>相比閉源軟件，這給予了開源項目擁有<strong>快速識別問題並儘快修復它們的能力</strong>的優勢。</p><p>不僅僅限於擁有更多的開發者，企業通常也會參與他們所使用的開源項目。當他們這樣做的時候，他們也會查閲代碼並審查它們。</p><p>這提供了另一條外部審查的途徑，而這可能有助於提升開源軟件的安全性。</p><p>反之，就閉源軟件而言，數量有限的開發者可能並不能找出所有種類的安全問題。而且他們可能需要花費更長的時間來一一修復發現的問題。</p><h4 id="社區決定安全問題的優先級" tabindex="-1">社區決定安全問題的優先級 <a class="header-anchor" href="#社區決定安全問題的優先級" aria-label="Permalink to “社區決定安全問題的優先級”">​</a></h4><p>閉源軟件的開發者可能在處理什麼問題和什麼時候解決問題等方面有某些限制或者優先等級。</p><p>而如果是開源項目，貢獻者社區可以自行決定優先級，並自行安排他們想解決的問題以及決定合適修復問題。你不需要依賴於供應商的決定或者按照他們的指示來解決一個安全問題。</p><p>着手處理和修復安全問題的決策在開源軟件項目中更加透明和靈活。因此，它可以被證明是更有效的，併為你帶來以下三個益處：</p><ul><li>透明度</li><li>不依賴供應商</li><li>更快的安全更新</li></ul><h3 id="開源軟件不是防彈的-以下是原因" tabindex="-1">開源軟件不是防彈的，以下是原因 <a class="header-anchor" href="#開源軟件不是防彈的-以下是原因" aria-label="Permalink to “開源軟件不是防彈的，以下是原因”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/wordpress/2021/07/open-source-security-issue.jpg" alt=""></p><p>雖然在某些情況下，開源軟件可能在安全性上具有優勢，然而仍有一些因素影響它。</p><p>承認這些問題的存在是很重要的，據此，企業或者個人可以就開源軟件的安全情況做出更好的決定。</p><h4 id="並無足夠的眼睛來審查代碼和不確定性" tabindex="-1">並無足夠的眼睛來審查代碼和不確定性 <a class="header-anchor" href="#並無足夠的眼睛來審查代碼和不確定性" aria-label="Permalink to “並無足夠的眼睛來審查代碼和不確定性”">​</a></h4><p>即使開源軟件代碼可以被全世界的開發者自由訪問，<strong>項目沒有足夠的貢獻者/開發者徹底審查開源代碼</strong>的可能性仍然存在。</p><p>既如此，我們不能對開源軟件的同行審查抱有極高的信心，因為它恰好缺失了這一點。</p><p>開源軟件可能“聲稱”擁有最高的安全性因為它們是開源的。在沒有足夠的開發者致力於該項目時，這是一種誤導。</p><p>同樣，我們也無從得知有多少開發者在查看/檢查代碼，也不知道代碼的檢查進行到什麼程度了。</p>',21)),r("p",null,[t[13]||(t[13]=s("舉例而言，",-1)),r("ruby",null,[p(e,{href:"https://www.cve.org/CVERecord?id=CVE-2014-0160"},{default:n(()=>[...t[11]||(t[11]=[s("心臟出血漏洞",-1)])]),_:1}),t[12]||(t[12]=r("rt",null,"Heartbleed",-1))]),t[14]||(t[14]=s(" 是在一個被廣泛使用的項目（OpenSSL）中引入了 2 年以後才被發現的。",-1))]),t[37]||(t[37]=o('<h4 id="軟件責任與問責" tabindex="-1">軟件責任與問責 <a class="header-anchor" href="#軟件責任與問責" aria-label="Permalink to “軟件責任與問責”">​</a></h4><p>對於個人用户這可能並不重要，但是<strong>開源項目通常並無任何保證</strong>。</p><p>因此，如果一家公司使用它，它們必須自行承擔任何由該軟件使用造成的數據丟失與損壞。</p><p>這告訴你，沒有什麼是 100% 安全和沒有漏洞的。無論有多少眼睛聚焦在代碼上或者貢獻者的技術多麼精湛，總會存在某種形式的風險，無論是安全風險還是數據丟失。</p><p>這告訴我們一個現實：開源軟件並非防彈的。</p><h3 id="開源軟件有其更高安全性的優勢-但是" tabindex="-1">開源軟件有其更高安全性的優勢，但是... <a class="header-anchor" href="#開源軟件有其更高安全性的優勢-但是" aria-label="Permalink to “開源軟件有其更高安全性的優勢，但是...”">​</a></h3><p>就安全性而言沒有什麼優勝者。不論是閉源還是開源，當涉及安全問題時都適用同一套原則。</p><p>有很多外部因素可以影響軟件安全性，而<strong>其中很多因素並不依賴於源代碼</strong>。</p><p>必須以某種形式監控代碼，以保證安全。</p><p>是的，<strong>開源道路提供了閉源軟件所不具備的優勢</strong>，但是這並不意味着開源軟件是防彈的。</p><p><em>你對開源軟件安全狀況有何思考？你又是否認為開源軟件比專有軟件解決方案更好呢？</em></p><p>提前感謝你在下面的評論中提出的寶貴意見。</p><hr>',13)),r("p",null,[t[16]||(t[16]=s("via: ",-1)),p(e,{href:"https://news.itsfoss.com/open-source-software-security/"},{default:n(()=>[...t[15]||(t[15]=[s("https://news.itsfoss.com/open-source-software-security/",-1)])]),_:1})]),r("p",null,[t[21]||(t[21]=s("作者：",-1)),p(e,{href:"https://news.itsfoss.com/author/ankush/"},{default:n(()=>[...t[17]||(t[17]=[s("Ankush Das",-1)])]),_:1}),t[22]||(t[22]=s(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[18]||(t[18]=[s("lujun9972",-1)])]),_:1}),t[23]||(t[23]=s(" 譯者：",-1)),p(e,{href:"https://github.com/CanYellow"},{default:n(()=>[...t[19]||(t[19]=[s("CanYellow",-1)])]),_:1}),t[24]||(t[24]=s(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[20]||(t[20]=[s("wxy",-1)])]),_:1})]),r("p",null,[t[27]||(t[27]=s("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[25]||(t[25]=[s("LCTT",-1)])]),_:1}),t[28]||(t[28]=s(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:n(()=>[...t[26]||(t[26]=[s("Linux中國",-1)])]),_:1}),t[29]||(t[29]=s(" 榮譽推出",-1))])])}const C=l(u,[["render",f]]);export{S as __pageData,C as default};
